 [Serializable]class Legacy {public int version=1,undo=3,hint=7,extra=1,shuffle=1;public DailyData daily;public List<LevelRecord> levels;public List<string> claimedMilestones;}
 public static void Models()
 {
  var now=new DateTimeOffset(2026,10,19,12,0,0,TimeSpan.FromHours(3));var l=new ProgressLedger(new ProgressData(),_=>{},()=>now);Check(l.ObserveHub()&&l.HubSnapshot.weekWins==0&&l.HubSnapshot.seasonWins==0,"Fresh offline periods initialized");Check(!l.ClaimWeekly()&&!l.ClaimSeason(0),"No unearned rewards");Check(!l.Claim(1,3,false,out _,"fake",2)&&l.HubSnapshot.weekWins==0,"Non victory cannot progress events");
  for(int i=1;i<=6;i++){Win(l,"run-"+i);Check(l.HubSnapshot.weekWins==Math.Min(i,3)&&l.HubSnapshot.seasonWins==i,"Actual receipt advances capped week and independent season "+i);Win(l,"run-"+i);Check(l.HubSnapshot.seasonWins==i,"Duplicate receipt blocked "+i);if(i==1)Check(!l.ClaimSeason(0),"Tier locked below threshold");}
  Check(l.DailySnapshot.progress[1]==2&&l.HubSnapshot.seasonWins==6,"Season advances after daily goals are already full");var ready=l.Snapshot;
  int before=l.Remaining(BoosterKind.Shuffle);Check(l.ClaimWeekly()&&l.Remaining(BoosterKind.Shuffle)==before+1&&l.OwnsCollection(RewardHubRules.StarBadge),"Weekly claim grants booster and existing star collectible atomically");for(int i=0;i<5;i++)Check(!l.ClaimWeekly()&&l.Remaining(BoosterKind.Shuffle)==before+1,"Weekly duplicate blocked "+i);
  for(int i=0;i<3;i++){int n=l.Remaining(RewardHubRules.Reward(i));Check(l.ClaimSeason(i)&&l.Remaining(RewardHubRules.Reward(i))==n+1,"Free tier reward "+i);Check(!l.ClaimSeason(i)&&l.Remaining(RewardHubRules.Reward(i))==n+1,"Free tier duplicate blocked "+i);}Check(l.OwnsCollection(RewardHubRules.WizardCard)&&l.HubSnapshot.owned.Count==2&&!l.OwnsCollection("unproduced.costume"),"Only two real registered collection items can be owned");Check(!l.ClaimSeason(-1)&&!l.ClaimSeason(3),"Unknown or premium tier cannot claim");
  var reload=new ProgressLedger(JsonUtility.FromJson<ProgressData>(JsonUtility.ToJson(l.Snapshot)),_=>{},()=>now);Check(reload.HubSnapshot.weeklyClaimed&&reload.HubSnapshot.seasonClaimed.All(x=>x)&&reload.HubSnapshot.owned.Count==2&&!reload.ClaimWeekly()&&!reload.ClaimSeason(2),"Serialized reload preserves ownership and all claim markers");var view=reload.HubSnapshot;view.owned.Clear();Check(reload.HubSnapshot.owned.Count==2,"Snapshot cannot mutate real ownership");
  var old=l.Snapshot;var legacy=JsonUtility.FromJson<ProgressData>(JsonUtility.ToJson(new Legacy{daily=old.daily,levels=old.levels,claimedMilestones=new List<string>{"map.village.v1"}}));var migrated=new ProgressLedger(legacy,_=>{},()=>now);Check(migrated.ObserveHub()&&migrated.Remaining(BoosterKind.Hint)==7&&migrated.BestStars(1)==3&&migrated.MilestoneClaimed("map.village.v1")&&migrated.DailySnapshot.progress[1]==2,"PART07A save migrates without dropping daily stars balances or map markers");
  var failed=new ProgressLedger(ready,_=>throw new IOException("test disk failure"),()=>now);int initial=failed.Remaining(BoosterKind.Shuffle);Check(!failed.ClaimWeekly()&&!failed.HubSnapshot.weeklyClaimed&&failed.Remaining(BoosterKind.Shuffle)==initial&&!failed.OwnsCollection(RewardHubRules.StarBadge),"Weekly save failure changes neither reward nor ownership");Check(!failed.ClaimSeason(2)&&!failed.HubSnapshot.seasonClaimed[2]&&!failed.OwnsCollection(RewardHubRules.WizardCard),"Season save failure leaves collectible and claim untouched");
  var brokenWin=new ProgressLedger(new ProgressData(),_=>throw new IOException("test"),()=>now);Check(!brokenWin.Claim(1,3,true,out _,"failed-win",2)&&brokenWin.HubSnapshot.weekWins==0&&!brokenWin.Completed(1),"Victory and event progress share failed commit");
  var full=ready.Copy();full.shuffle=int.MaxValue;var overflow=new ProgressLedger(full,_=>{},()=>now);Check(!overflow.ClaimWeekly()&&!overflow.HubSnapshot.weeklyClaimed&&!overflow.OwnsCollection(RewardHubRules.StarBadge),"Weekly overflow cannot award collectible");full=ready.Copy();full.extra=int.MaxValue;overflow=new ProgressLedger(full,_=>{},()=>now);Check(!overflow.ClaimSeason(2)&&!overflow.OwnsCollection(RewardHubRules.WizardCard),"Season overflow cannot award collectible");
  var invalid=ready.Copy();invalid.hub.owned.Add("missing.asset");Throws(()=>new ProgressLedger(invalid,_=>{}),"Unproduced collection id rejected on load");invalid=ready.Copy();invalid.hub.weekWins=2;Throws(()=>new ProgressLedger(invalid,_=>{}),"Counter and receipt mismatch rejected");
  now=now.AddDays(7);Check(l.ObserveHub()&&l.HubSnapshot.weekWins==0&&!l.HubSnapshot.weeklyClaimed&&l.HubSnapshot.seasonWins==6&&l.HubSnapshot.owned.Count==2,"Monday resets weekly progress but preserves season and lifetime collection");for(int i=0;i<3;i++)Win(l,"week-two-"+i);before=l.Remaining(BoosterKind.Shuffle);Check(l.ClaimWeekly()&&l.Remaining(BoosterKind.Shuffle)==before+1&&l.HubSnapshot.owned.Count==2,"New week can reward again without duplicating collection");
  now=now.AddDays(28);Check(l.ObserveHub()&&l.HubSnapshot.seasonWins==0&&l.HubSnapshot.seasonClaimed.All(x=>!x)&&l.HubSnapshot.owned.Count==2,"New season resets free path but retains owned items");var high=now;now=now.AddDays(-2);Check(l.HubClockBlocked&&!l.ObserveHub()&&!l.ClaimWeekly()&&!l.ClaimSeason(0),"Rollback blocks event rewards");Win(l,"rollback-run");Check(l.HubSnapshot.weekWins==0&&l.HubSnapshot.seasonWins==0,"Rollback cannot accumulate event progress");now=high;Check(l.ObserveHub()&&!l.HubClockBlocked,"Clock recovery at recorded high water");
  string key="Mewgic.Tests.Part07B."+Guid.NewGuid().ToString("N");try{var disk=GameplayProgress.Open(key,()=>now);for(int i=0;i<6;i++)Win(disk,"disk-"+i);Check(disk.ClaimWeekly()&&disk.ClaimSeason(2),"Actual PlayerPrefs awards saved");var again=GameplayProgress.Open(key,()=>now);Check(again.HubSnapshot.owned.Count==2&&!again.ClaimWeekly()&&!again.ClaimSeason(2)&&again.HubSnapshot.seasonWins==6,"Actual disk reload prevents duplicate rewards and retains collection");}finally{PlayerPrefs.DeleteKey(key);PlayerPrefs.Save();}
 }
 static RewardHubPanel Hub=>UnityEngine.Object.FindFirstObjectByType<RewardHubPanel>();static Puzzle Model()=>(Puzzle)typeof(PrototypeApp).GetField("puzzle",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(UnityEngine.Object.FindFirstObjectByType<PrototypeApp>());
 static void Add(Action a)=>actions.Enqueue(a);static void Tap(string name)=>Add(()=>Click(name));
 static void Click(string name){Canvas.ForceUpdateCanvases();var g=GameObject.Find(name);Check(g!=null,"Button exists "+name);var r=(RectTransform)g.transform;var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(hits.Count>0&&hits[0].gameObject==g,"Actual top raycast "+name);ExecuteEvents.Execute(g,d,ExecuteEvents.pointerClickHandler);}
 public static void Run()
 {
  if(EditorApplication.isPlaying)throw new Exception("Stop Play first");checks.Clear();actions.Clear();Models();had=PlayerPrefs.HasKey(GameplayProgress.StorageKey);original=PlayerPrefs.GetString(GameplayProgress.StorageKey,"");GameplayProgress.UseTestProfile();GameplayLevelCatalog.ResetSelection();
  Add(HomeEntries);Tap("CollectionButton");Add(()=>Check(Hub.IsOpen&&GameplayProgress.Current.HubSnapshot.owned.Count==0,"Home Collection opens real empty gallery"));Tap("CollectionView_0");Add(()=>Check(Hub.InformationVisible&&!GameObject.Find("OwnedCollectionPreview"),"Locked item explains real earning condition"));Tap("RewardInfoClose");Tap("RewardTab_0");Tap("HubOpenDaily");Add(()=>Check(UnityEngine.Object.FindFirstObjectByType<Mewgic.Daily.DailyActivitiesPanel>().IsOpen,"Daily tab opens preserved daily screen"));Tap("DailyClose");Add(()=>Check(Hub.IsOpen,"Daily back returns to reward center"));Tap("RewardHubClose");Tap("NavEvents");
  Add(()=>{Check(Hub.IsOpen,"Home bottom Events opens real reward center");Capture(900,1600);Capture(900,1950);Capture(900,2000);Capture(900,2000,true);Capture(360,640);Hub.FocusSection(0);var drag=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,Hub.Scroll.viewport.position)};Hub.Scroll.OnInitializePotentialDrag(drag);Hub.Scroll.OnBeginDrag(drag);drag.position+=new Vector2(0,250);Hub.Scroll.OnDrag(drag);Hub.Scroll.OnEndDrag(drag);Check(Hub.Scroll.verticalNormalizedPosition<.99f,"Real pointer drag scrolls reward center");Hub.Scroll.StopMovement();Hub.FocusSection(0);});Add(()=>ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART07B_OVERVIEW_GAMEVIEW.png"));Tap("RewardTab_1");Add(()=>Check(!GameObject.Find("ClaimWeekly").GetComponent<Button>().interactable,"Weekly button is locked before wins"));Tap("WeeklyGo");
  for(int run=1;run<=6;run++){int number=run;foreach(var move in PuzzleSolver.Solve(GameplayLevelCatalog.Load(1).Bottles).Moves){int a=move.Source,b=move.Target;Tap("Bottle "+(a+1));Tap("Bottle "+(b+1));}Add(()=>Check(Model().Won&&GameplayProgress.Current.HubSnapshot.weekWins==Math.Min(number,3)&&GameplayProgress.Current.HubSnapshot.seasonWins==number,"Actual gameplay win advances event once "+number));Tap("ResultHome");if(run<6)Tap("Play");}
  Tap("EventsButton");Add(()=>ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART07B_WEEKLY_READY_GAMEVIEW.png"));Tap("ClaimWeekly");Add(()=>Check(GameplayProgress.Current.OwnsCollection(RewardHubRules.StarBadge)&&GameplayProgress.Current.Remaining(BoosterKind.Shuffle)==2,"Real weekly claim owns star and one shuffle"));Tap("ClaimWeekly");Add(()=>Check(GameplayProgress.Current.Remaining(BoosterKind.Shuffle)==2,"Repeated disabled weekly press cannot award twice"));Tap("RewardTab_2");Add(()=>ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART07B_SEASON_READY_GAMEVIEW.png"));Tap("ClaimSeason_0");Tap("ClaimSeason_1");Tap("ClaimSeason_2");Add(()=>Check(GameplayProgress.Current.HubSnapshot.seasonClaimed.All(x=>x)&&GameplayProgress.Current.OwnsCollection(RewardHubRules.WizardCard),"Real free track claims all rewards and existing cat card"));Tap("PremiumInfo");Add(()=>{Check(Hub.InformationVisible&&GameplayProgress.Current.Remaining(BoosterKind.Hint)==5&&GameplayProgress.Current.HubSnapshot.owned.Count==2,"Premium only explains feature without purchase or balance mutation");ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART07B_PREMIUM_INFO_GAMEVIEW.png");});Tap("RewardInfoClose");Tap("RewardTab_3");Add(()=>ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART07B_COLLECTION_GAMEVIEW.png"));Tap("CollectionView_1");Add(()=>{Check(Hub.InformationVisible&&GameObject.Find("OwnedCollectionPreview").GetComponent<Image>().sprite!=null,"Owned collection displays real existing art");ScreenCapture.CaptureScreenshot("C:/Dev/Mewgic/docs/PART07B_OWNED_CARD_GAMEVIEW.png");});Tap("RewardInfoClose");Tap("RewardHubClose");Tap("NavMap");Add(()=>Check(UnityEngine.SceneManagement.SceneManager.GetActiveScene().name=="LevelMap","Existing Map navigation preserved"));Tap("MapHome");
  SessionState.SetBool("RewardHubTest",true);EditorSceneManager.OpenScene("Assets/Scenes/Home.unity");EditorApplication.isPlaying=true;next=EditorApplication.timeSinceStartup+2;
