 static Rect Bounds(RectTransform r,RectTransform relative,bool pad=false){var v=r.rect;if(pad){var p=r.GetComponent<Image>().raycastPadding;v=Rect.MinMaxRect(v.xMin+p.x,v.yMin+p.y,v.xMax-p.z,v.yMax-p.w);}var min=(Vector2)relative.InverseTransformPoint(r.TransformPoint(v.min));var max=(Vector2)relative.InverseTransformPoint(r.TransformPoint(v.max));return Rect.MinMaxRect(min.x,min.y,max.x,max.y);}
 public static void Capture(int width,int height,bool inset=false)
 {
  var hub=Hub;var safe=hub.Safe;var canvas=safe.GetComponentInParent<Canvas>();var camera=Camera.main;var mode=canvas.renderMode;var cam=canvas.worldCamera;var plane=canvas.planeDistance;var min=safe.anchorMin;var max=safe.anchorMax;var target=camera.targetTexture;var old=RenderTexture.active;var rt=new RenderTexture(width,height,24);Texture2D tex=null;
  try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;camera.targetTexture=rt;if(inset){safe.anchorMin=new Vector2(.04f,.05f);safe.anchorMax=new Vector2(.96f,.96f);}Canvas.ForceUpdateCanvases();hub.Layout();Canvas.ForceUpdateCanvases();var content=(RectTransform)GameObject.Find("RewardContent").transform;var all=hub.Root.GetComponentsInChildren<Button>();
   foreach(var b in all){var r=(RectTransform)b.transform;var reference=r.IsChildOf(content)?content:safe;var box=Bounds(r,reference,true);float factor=canvas.scaleFactor*canvas.transform.InverseTransformVector(r.TransformVector(Vector3.right)).magnitude;var padding=r.GetComponent<Image>().raycastPadding;Check((r.rect.width-padding.x-padding.z)*factor>=43.9f&&(r.rect.height-padding.y-padding.w)*factor>=43.9f,"44px reward hit area "+b.name+width);Check(reference.rect.Contains(box.min)&&reference.rect.Contains(box.max),"Button within safe or scroll content "+b.name+height);}
   var scrolling=all.Where(b=>b.transform.IsChildOf(content)).ToArray();for(int i=0;i<scrolling.Length;i++)for(int j=i+1;j<scrolling.Length;j++)Check(!Bounds((RectTransform)scrolling[i].transform,content,true).Overlaps(Bounds((RectTransform)scrolling[j].transform,content,true)),"Nonoverlapping reward hit areas "+scrolling[i].name+"/"+scrolling[j].name+width);
   Check(hub.Scroll.vertical&&!hub.Scroll.horizontal&&hub.Scroll.viewport.GetComponent<RectMask2D>()!=null,"Vertical clipped reward content "+height);
   for(int section=0;section<4;section++){hub.FocusSection(section);Canvas.ForceUpdateCanvases();camera.Render();if(width==900&&height==1600||section==2){RenderTexture.active=rt;tex=new Texture2D(width,height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,width,height),0,0);tex.Apply();File.WriteAllBytes("docs/PART07B_LAYOUT_"+width+"x"+height+(inset?"_SAFE":"")+"_SECTION"+section+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);tex=null;}}
   hub.FocusSection(0);var hidden=GameObject.Find("CollectionView_0");var d=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(camera,hidden.transform.position)};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(d,hits);Check(!hits.Any(h=>h.gameObject==hidden),"Clipped offscreen collection cannot receive touches "+height);
  }finally{camera.targetTexture=target;RenderTexture.active=old;canvas.renderMode=mode;canvas.worldCamera=cam;canvas.planeDistance=plane;safe.anchorMin=min;safe.anchorMax=max;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();hub.Layout();hub.FocusSection(0);}
 }
 static Rect VisualBounds(RectTransform r,RectTransform relative)
 {var local=r.rect;var image=r.GetComponent<Image>();if(image!=null&&image.preserveAspect&&image.sprite!=null){var size=image.sprite.rect.size;float scale=Mathf.Min(local.width/size.x,local.height/size.y);local=new Rect(local.center-size*scale*.5f,size*scale);}Vector2 a=(Vector2)relative.InverseTransformPoint(r.TransformPoint(local.min)),b=(Vector2)relative.InverseTransformPoint(r.TransformPoint(local.max));return Rect.MinMaxRect(a.x,a.y,b.x,b.y);}
 static void HomeEntries()
 {
  foreach(var shape in new[]{new Vector2Int(900,1600),new Vector2Int(900,1950),new Vector2Int(900,2000),new Vector2Int(360,640)}){
   var hub=Hub;var safe=hub.Safe;var canvas=safe.GetComponentInParent<Canvas>();var camera=Camera.main;var mode=canvas.renderMode;var cam=canvas.worldCamera;var plane=canvas.planeDistance;var target=camera.targetTexture;var old=RenderTexture.active;var rt=new RenderTexture(shape.x,shape.y,24);Texture2D tex=null;
   try{canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=1;camera.targetTexture=rt;Canvas.ForceUpdateCanvases();UnityEngine.Object.FindFirstObjectByType<HomeCharacterPresenter>().Layout();UnityEngine.Object.FindFirstObjectByType<HomePotionDisplay>().Layout();hub.Layout();Canvas.ForceUpdateCanvases();var first=Bounds((RectTransform)GameObject.Find("EventsButton").transform,safe,true);var second=Bounds((RectTransform)GameObject.Find("CollectionButton").transform,safe,true);Check(!first.Overlaps(second),"Home event and collection touch targets do not overlap "+shape);
    foreach(var name in new[]{"EventsButton","CollectionButton"}){var r=(RectTransform)GameObject.Find(name).transform;var box=Bounds(r,safe,true);Check(safe.rect.Contains(box.min)&&safe.rect.Contains(box.max),"New Home entry inside safe "+name+shape);Check(box.width*canvas.scaleFactor>=43.9f&&box.height*canvas.scaleFactor>=43.9f,"Home entry44px target "+name+shape);foreach(var other in new[]{"Play","MewgicLogo","HomeBottomNavigation","RightPotion/BaseSprite"})Check(!box.Overlaps(VisualBounds((RectTransform)GameObject.Find(other).transform,safe)),"Home entry avoids "+other+shape);Check(!box.Overlaps(VisualBounds(UnityEngine.Object.FindFirstObjectByType<HomeCharacterPresenter>().character,safe)),"Home entry avoids cat "+shape);}
    camera.Render();RenderTexture.active=rt;tex=new Texture2D(shape.x,shape.y,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,shape.x,shape.y),0,0);tex.Apply();File.WriteAllBytes("docs/PART07B_HOME_LAYOUT_"+shape.x+"x"+shape.y+".png",tex.EncodeToPNG());
   }finally{camera.targetTexture=target;RenderTexture.active=old;canvas.renderMode=mode;canvas.worldCamera=cam;canvas.planeDistance=plane;if(tex!=null)UnityEngine.Object.DestroyImmediate(tex);rt.Release();UnityEngine.Object.DestroyImmediate(rt);Canvas.ForceUpdateCanvases();UnityEngine.Object.FindFirstObjectByType<HomeCharacterPresenter>().Layout();UnityEngine.Object.FindFirstObjectByType<HomePotionDisplay>().Layout();hub.Layout();}
  }
 }
 [Serializable]class Result{public bool success;public int count;public string error;public string[] checks;}
 static void Finish(string error){SessionState.SetBool("RewardHubTest",false);if(PlayerPrefs.HasKey(GameplayProgress.StorageKey)!=had||PlayerPrefs.GetString(GameplayProgress.StorageKey,"")!=original)error=(error??"")+" Player save changed";else checks.Add("Real player save unchanged");File.WriteAllText("docs/PART07B_TEST_RESULTS.json",JsonUtility.ToJson(new Result{success=error==null,count=checks.Count,error=error,checks=checks.ToArray()},true));EditorApplication.isPlaying=false;GameplayProgress.RestorePlayerProfile();GameplayLevelCatalog.ResetSelection();}
 static void Tick(){if(!SessionState.GetBool("RewardHubTest",false)||!EditorApplication.isPlaying||EditorApplication.timeSinceStartup<next)return;try{next=EditorApplication.timeSinceStartup+1.15;if(actions.Count==0){Finish(null);return;}actions.Dequeue()();}catch(Exception e){Finish(e.ToString());}}
}
